import{_ as p,a0 as a,w as r,s as u,I as i,x as n,a1 as s,A as e,ao as f}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const N=JSON.parse('{"title":"使用“最近通知工具”保持桌面通知历史 | LCTT x X-CMD","titleTemplate":false,"description":"使用“最近通知工具”保持桌面通知历史 | LCTT (201503) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用“最近通知工具”保持桌面通知历史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用“最近通知工具”保持桌面通知历史 | LCTT (201503) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator","title":"使用“最近通知工具”保持桌面通知历史","tag":"201503","desc":""},"relativePath":"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator.md","filePath":"[post].md"}'),d={name:"201503/20150123 Keep History Of Notifications With Recent Notifications AppIndicator.md"};function l(m,t,T,b,g,C){const o=a("Link");return r(),u("div",null,[t[16]||(t[16]=i("h1",{id:"使用-最近通知工具-保持桌面通知历史",tabindex:"-1"},[n("使用“最近通知工具”保持桌面通知历史 "),i("a",{class:"header-anchor",href:"#使用-最近通知工具-保持桌面通知历史","aria-label":"Permalink to “使用“最近通知工具”保持桌面通知历史”"},"​")],-1)),t[17]||(t[17]=i("p",null,[i("img",{src:"http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu_14.jpeg",alt:"How to see recent notifications in Ubuntu 14.04"})],-1)),i("p",null,[t[1]||(t[1]=n("大多数桌面环境像Unity和Gnome都有通知特性。我很喜欢其中一些。它尤其当我",-1)),s(o,{href:"http://itsfoss.com/apps-internet-streaming-radio-ubuntu/"},{default:e(()=>[...t[0]||(t[0]=[n("在Ubuntu上收听流媒体",-1)])]),_:1}),t[2]||(t[2]=n("时帮到我。默认上通知会在桌面的顶部显示几秒接着就会消失。如果你听见了通知的声音但是没有看到内容怎么办？你该如何知道通知的内容？",-1))]),t[18]||(t[18]=f(`<p>如果你可以看到最近所有通知的历史会很棒吧？是的，我知道这很棒。你可以在Ubuntu Unity或者Gnome中使用最近<strong>通知小工具</strong>来追踪所有的最近通知。</p><p>最近通知位于顶部面板，并且记录了最近所有通知的历史。当它捕获到新的通知后，它就会变绿来表明你有未读的通知。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu.jpeg" alt="Recent notifications in Ubuntu 14.04"></p><p>当你点击它后，你就会看到最近所有的通知。你可以选择清空所有或者删除部分。</p><p><img src="http://itsfoss.itsfoss.netdna-cdn.com/wp-content/uploads/2015/01/recent_notifications_Ubuntu_1.jpeg" alt="Recent notifications applet indicator"></p><p>不幸的是它没有配置选项。因此你不能屏蔽特定程序的通知。所有的通知都会被保存。</p><h3 id="在ubuntu-14-04-和-14-10-中安装最近通知工具" tabindex="-1">在Ubuntu 14.04 和 14.10 中安装最近通知工具 <a class="header-anchor" href="#在ubuntu-14-04-和-14-10-中安装最近通知工具" aria-label="Permalink to “在Ubuntu 14.04 和 14.10 中安装最近通知工具”">​</a></h3><p>一般说来这个最近通知工具应该也可以在Linux Mint Cinnamon版本中运行。你可以试一试。使用下面的命令来在在Ubuntu 14.04 和 14.10 中安装最近通知工具：</p><pre><code>sudo add-apt-repository ppa:jconti/recent-notifications
sudo apt-get update
sudo apt-get install indicator-notifications
</code></pre><p>安装完成后，重新登录后你就可以用了。现在妈妈再也不用担心我的通知没看到了。很方便的小工具，不是么？</p><hr>`,11)),i("p",null,[t[4]||(t[4]=n("via: ",-1)),s(o,{href:"http://itsfoss.com/notifications-appindicator/"},{default:e(()=>[...t[3]||(t[3]=[n("http://itsfoss.com/notifications-appindicator/",-1)])]),_:1})]),i("p",null,[t[8]||(t[8]=n("作者：",-1)),s(o,{href:"http://itsfoss.com/author/Abhishek/"},{default:e(()=>[...t[5]||(t[5]=[n("Abhishek",-1)])]),_:1}),t[9]||(t[9]=n(" 译者：",-1)),s(o,{href:"https://github.com/geekpi"},{default:e(()=>[...t[6]||(t[6]=[n("geekpi",-1)])]),_:1}),t[10]||(t[10]=n(" 校对：",-1)),s(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[7]||(t[7]=[n("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=n("本文由 ",-1)),s(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[n("LCTT",-1)])]),_:1}),t[14]||(t[14]=n(" 原创翻译，",-1)),s(o,{href:"http://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[n("Linux中国",-1)])]),_:1}),t[15]||(t[15]=n(" 荣誉推出",-1))])])}const U=p(d,[["render",l]]);export{N as __pageData,U as default};
